# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span


class RoundLabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        self.assertEqual(
            round_labels([Span(9 * 60 + 2, 17 * 60 + 12)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        labels = round_labels([Span(0, 60), Span(61, 130)], 30)
        self.assertEqual(labels, ["00:00-01:00 (1h 0m)", "01:00-02:00 (1h 0m)"])

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_labels([Span(60, 120)], step)


if __name__ == "__main__":
    unittest.main()
